import{_ as t,o as d,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"ioBroker: automatische Rollenzuordnung","description":"","frontmatter":{},"headers":[],"relativePath":"projects/mqtt-client/iobroker-roles.md","filePath":"projects/mqtt-client/iobroker-roles.md","lastUpdated":1794046324000}'),o={name:"projects/mqtt-client/iobroker-roles.md"};function i(a,e,c,s,l,u){return d(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="iobroker-role-mapping" tabindex="-1">ioBroker: automatische Rollenzuordnung <a class="header-anchor" href="#iobroker-role-mapping" aria-label="Permalink to &quot;ioBroker: automatische Rollenzuordnung {#iobroker-role-mapping}&quot;">​</a></h1><p>Das optionale JavaScript gehört zu MQTT-Client <strong>0.1.25</strong> und läuft im ioBroker-JavaScript-Adapter. Es verwendet die übertragenen Metadaten <code>device_class</code> und <code>unit_of_measurement</code>. Es ordnet nur eindeutige Fälle zu; weder MQTT-Werte noch Datentypen, Einheiten, Zugangsdaten oder Rückkanäle werden umgeschrieben.</p><h2 id="fix-0125" tabindex="-1">Korrektur 0.1.25: fehlende Objekte ohne Warnungen <a class="header-anchor" href="#fix-0125" aria-label="Permalink to &quot;Korrektur 0.1.25: fehlende Objekte ohne Warnungen {#fix-0125}&quot;">​</a></h2><p>In JavaScript-Adapter <strong>10.4.10</strong> warnt auch <code>getObject</code> bei fehlenden IDs. Der Helfer prüft jetzt mit <code>existsObject</code> und <code>existsState</code>, bevor er Objekte oder Zustände liest. Das gilt für Journal, optionale Metadaten, Ordner und noch nicht angelegte virtuelle Datenpunkte. Die vorherige Prüfung über <code>getObject</code> allein reichte nicht aus.</p><p>In der Vorschau erscheinen <code>Preview VIS 2</code>-Zeilen, aber es wird nichts angelegt. Für die automatische Anlage nach der Prüfung <code>mode: &#39;apply&#39;</code> setzen. In der JavaScript-Instanz <code>setObject</code> erlauben und <strong>Do not subscribe to all states on start</strong> deaktivieren, weil der Helfer synchron aus den Zustands-Caches liest. Eine abgebrochene eigene Neuanlage kann nach der Freigabe erneut versucht werden; fremde oder bearbeitete Datenpunkte bleiben geschützt.</p><p>MQTT-Client <strong>ab 0.1.24</strong> liefert den benötigten Auswahlkatalog; für diese Korrektur genügt der Austausch der vollständigen Helferdatei. Alte nicht mehr ausgewählte Retain-Topics ohne aktuelle Entitätskennung werden ausgelassen. Fehlende HA-Metadaten werden nicht vom Helfer erfunden. Die Startmeldung nennt jetzt Version und Betriebsmodus.</p><p>Der Helfer bündelt echte MQTT-Änderungen für eine Sekunde. Im virtuellen Modus werden nur die betroffenen Quellen verarbeitet; unveränderte Wiederholungen und fremde Attribute lösen keinen Durchlauf aus. Eine Vollprüfung erfolgt beim Start und bei Änderungen des Auswahlkatalogs oder der Verfügbarkeit. Die Befehls-Zeitprüfung betrifft nur ausstehende Quellen und endet nach Bestätigung oder Zeitablauf. Der Client abonniert pro Entität nur noch den zum Status passenden Rückkanal; alte ioBroker-Objekte werden nicht gelöscht.</p><h2 id="vis2" tabindex="-1">Neu in 0.1.24: ein VIS-2-Datenpunkt für Status und Befehl <a class="header-anchor" href="#vis2" aria-label="Permalink to &quot;Neu in 0.1.24: ein VIS-2-Datenpunkt für Status und Befehl {#vis2}&quot;">​</a></h2><p>Das Skript richtet jetzt automatisch virtuelle Datenpunkte und Ordner unter <code>0_userdata.0.ugso_mqtt</code> ein. Es ist für die APIs des ioBroker-JavaScript-Adapters <strong>10.4.10</strong> ausgelegt. Zuerst <strong>MQTT-Client auf 0.1.24 aktualisieren</strong> und den Client neu verbinden: Der neue Auswahlkatalog bindet Entität, aktuellen Topic-Pfad und Befehlsfreigabe eindeutig zusammen. Alte Retain-Topics dürfen dadurch keine zusätzlichen Steuerungen erzeugen.</p><p>Oben im vollständigen Skript bleiben zunächst diese Einstellungen:</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">outputMode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;virtual&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;preview&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mqttRoot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;mqtt.0.ha_external&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">virtualRoot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0_userdata.0.ugso_mqtt&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">virtualBackupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0_userdata.0.ugso_mqtt_helper.backup&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Nach Prüfung der Vorschau auf <code>mode: &#39;apply&#39;</code> wechseln und neu starten. <strong>Sicherungsdatenpunkt, Ordner und neue VIS-2-Datenpunkte werden automatisch angelegt.</strong> In der Vorschau wird absichtlich nichts angelegt. Vorhandene fremde Datenpunkte, Aliase und manuelle Rollen werden nicht überschrieben. Deinen bisherigen Alias, zum Beispiel unter <code>alias.0.HA</code>, musst du nicht entfernen.</p><p>Beispiel: Aus <code>mqtt.0.ha_external.claudia_pc.switch.state</code> und dem zugehörigen <code>mqtt.0.ha_external.claudia_pc.switch.set</code> entsteht <code>0_userdata.0.ugso_mqtt.claudia_pc.switch.state</code>. <strong>Nur diesen virtuellen Datenpunkt in VIS 2 verwenden.</strong></p><table tabindex="0"><thead><tr><th>Richtung/Funktion</th><th>Verhalten</th></tr></thead><tbody><tr><td>MQTT-Status → VIS 2</td><td>Bestätigter Zustand mit <code>ack: true</code></td></tr><tr><td>VIS-2-Bedienung → MQTT-Befehl</td><td>Nur aktuelle Bedienungen mit <code>ack: false</code> gehen an <code>/set</code></td></tr><tr><td>Schalter</td><td><code>on</code>/<code>off</code> werden virtuell Boolean; zurück werden <code>ON</code>/<code>OFF</code> gesendet</td></tr><tr><td>Helligkeit</td><td>Prozentwert 0–100, Grenzen geprüft</td></tr><tr><td>RGB</td><td>MQTT-JSON-Array ↔ virtuelle Hexfarbe <code>#RRGGBB</code></td></tr><tr><td>Effekt</td><td>Nur Einträge der aktuellen Effektliste</td></tr><tr><td>Farbtemperatur</td><td>Ganze Kelvinzahl innerhalb der aktuellen Grenzen</td></tr><tr><td>Zahlen, Selects und Text</td><td>Vorhandene Grenzen beziehungsweise Optionen geprüft</td></tr><tr><td>Datum, Messwerte und Batterie</td><td>Lesend; vorhandene MQTT-Werte bleiben unverändert</td></tr></tbody></table><p>Es gibt keine Schaltbefehle beim Anlegen, Starten oder Neustarten und keine automatische Wiederholung alter Bedienungen. Eine neue HA-Rückmeldung bestätigt den Wert; die Brokerannahme allein ist keine Ausführungsbestätigung. Fehlt eine neue Rückmeldung etwa 30 Sekunden lang, bleibt der Auftrag unbestätigt und erhält Fehlerqualität <code>q: 128</code>. Bei fehlender Auswahl, unbekanntem Wert oder Offline-Zustand bleibt der letzte Wert mit <code>q: 130</code> erhalten. Befehle werden dann gesperrt. Keine Ersatzwerte wie Null oder Aus erfinden.</p><p>Das Journal unter <code>virtualBackupId</code> wird vor jeder Neuanlage gespeichert und geprüft. Es enthält Zuordnungen und Objektdefinitionen, keine MQTT-Zugangsdaten oder aktuellen Messwerte. Vorhandene MQTT-Datenpunkte werden im virtuellen Modus nicht verändert. Bei <code>mode: &#39;restore&#39;</code> bleiben virtuelle Werte und Dashboard-Verknüpfungen erhalten; eigene virtuelle Befehlsdatenpunkte werden schreibgeschützt und die Synchronisierung endet. Danach das Skript stoppen.</p><p>Die bisherige Funktion bleibt über <code>outputMode: &#39;roles&#39;</code> verfügbar. Die folgenden direkten Rollen-/Aliasregeln und deren Wiederherstellung beziehen sich auf diesen Rollenmodus; die Zuordnungstabellen gelten fachlich auch für virtuelle Datenpunkte. <strong>Nur eine Kopie des Helfers gleichzeitig ausführen.</strong> Fehlende optionale Attribute und ein noch nicht angelegtes Journal werden ohne die bisherigen <code>getState</code>-Warnungen behandelt.</p><h2 id="installation" tabindex="-1">Installation und Sicherung <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation und Sicherung {#installation}&quot;">​</a></h2><ol><li>Vorher im ioBroker-Admin die betroffenen MQTT-Objekte einschließlich Zuständen und vorhandenen Skripten exportieren beziehungsweise eine vollständige Sicherung erstellen.</li><li>Im MQTT-Client <strong>ioBroker-/VIS-2-Helfer herunterladen</strong> wählen oder <a href="https://raw.githubusercontent.com/rockbaer2007/ugso-ha-mqtt-addons/master/mqtt_client/app/iobroker/ugso-mqtt-role-mapper.js" target="_blank" rel="noreferrer">die Skriptdatei laden</a>.</li><li>Im ioBroker unter <strong>Skripte</strong> ein neues <strong>JavaScript</strong> anlegen und den gesamten Dateiinhalt einfügen. Es genügt ein Skript in einer JavaScript-Instanz.</li><li>Oben <code>mqttRoot</code> auf den eigenen MQTT-Pfad einstellen, zum Beispiel <code>mqtt.0.ha_external</code>. Der Pfad darf keine Platzhalter enthalten.</li><li>Zunächst <code>mode: &#39;preview&#39;</code> beibehalten, starten und das JavaScript-Protokoll prüfen. Die Vorschau schreibt nichts.</li><li>Manuell als <code>state</code> verwendete Datenpunkte in <code>excludeIds</code> eintragen. Eine solche manuelle Standardrolle ist von der automatisch vergebenen Rolle nicht unterscheidbar.</li><li>Nach der Kontrolle <code>mode: &#39;apply&#39;</code> setzen und das Skript neu starten. In den Einstellungen der JavaScript-Instanz muss die Verwendung von <code>setObject</code> erlaubt sein. Die Instanz muss die MQTT-Zustände lesen können.</li></ol><p>Vor jeder Änderung wird die ursprüngliche Rolle im JSON-Datenpunkt <code>0_userdata.0.ugso_mqtt_roles.backup</code> gespeichert und die Speicherung bestätigt. Der Datenpunkt enthält keine Zählerwerte oder Zugangsdaten. Bei einem Sicherungsfehler erfolgt keine nachfolgende Rollenänderung. Den Sicherungsdatenpunkt zusätzlich exportieren und nicht löschen.</p><p>Spezialrollen wie <code>date</code>, <code>text</code> oder <code>value.temperature</code> werden nicht ersetzt. Nach einer späteren manuellen Rollenänderung übernimmt das Skript diesen Datenpunkt nicht erneut. Vorhandene Aliase werden nie überschrieben.</p><h2 id="aliases" tabindex="-1">Direkte Rollen und schreibgeschützte Aliase <a class="header-anchor" href="#aliases" aria-label="Permalink to &quot;Direkte Rollen und schreibgeschützte Aliase {#aliases}&quot;">​</a></h2><p>Datum und Zeitstempel erhalten direkt die Rolle <code>date</code>. Der gespeicherte Text und die Schreibrechte bleiben erhalten; auch <code>uptime</code> ist in HA ein Startzeitpunkt, keine Laufzeitdauer.</p><p>Messwert- und Binärsensorrollen sind in ioBroker schreibgeschützt. Ist das MQTT-Original bereits schreibgeschützt, wird nur seine allgemeine Rolle ersetzt. Ist es schreibbar, entsteht stattdessen ein lesender Alias unter <code>alias.0.ugso_mqtt_roles</code>; Rolle und Schreibrechte des MQTT-Originals bleiben erhalten. Den Alias für Visualisierung und Auswertung verwenden. Seine Werte stammen weiterhin aus dem ursprünglichen MQTT-Datenpunkt.</p><p>Das Skript prüft Metadaten und tatsächlichen Werttyp. Aus Gerätenamen oder <code>on</code>/<code>off</code>-Texten werden keine Typen geraten. Fehlende Metadaten, abweichende Einheiten, ungültige Datumswerte und unbekannte Klassen werden ausgelassen. Es erzeugt keine Umrechnungen oder Steuerbefehle. <code>device_class</code> muss übertragen werden, bei Messwerten zusätzlich die Einheit; bei manueller Auswahl diese vorhandenen Attribute mit auswählen. Die Label-Funktion liefert vorhandene Standardattribute automatisch.</p><table tabindex="0"><thead><tr><th>HA-Geräteklasse</th><th>ioBroker-Rolle</th><th>Prüfung</th></tr></thead><tbody><tr><td><code>date</code></td><td><code>date</code></td><td>Gültiges <code>YYYY-MM-DD</code></td></tr><tr><td><code>timestamp</code>, <code>uptime</code></td><td><code>date</code></td><td>ISO-Zeitstempel mit Zeitzone</td></tr></tbody></table><h2 id="numeric" tabindex="-1">Umgesetzte numerische Zuordnungen <a class="header-anchor" href="#numeric" aria-label="Permalink to &quot;Umgesetzte numerische Zuordnungen {#numeric}&quot;">​</a></h2><p>Diese Tabelle nennt die tatsächlich akzeptierten Einheiten. Andere Einheiten bleiben unverändert; auch beispielsweise mA oder mV werden nicht stillschweigend umgerechnet.</p><table tabindex="0"><thead><tr><th>HA-Geräteklasse</th><th>ioBroker-Rolle</th><th>Akzeptierte Einheiten</th></tr></thead><tbody><tr><td><code>temperature</code></td><td><code>value.temperature</code></td><td><code>°C</code>, <code>°F</code>, <code>K</code></td></tr><tr><td><code>humidity</code></td><td><code>value.humidity</code></td><td><code>%</code></td></tr><tr><td><code>absolute_humidity</code></td><td><code>value.humidity.absolute</code></td><td><code>g/m³</code>, <code>mg/m³</code></td></tr><tr><td><code>battery</code></td><td><code>value.battery</code></td><td><code>%</code></td></tr><tr><td><code>voltage</code></td><td><code>value.voltage</code></td><td><code>V</code></td></tr><tr><td><code>current</code></td><td><code>value.current</code></td><td><code>A</code></td></tr><tr><td><code>power</code></td><td><code>value.power</code></td><td><code>W</code>, <code>kW</code></td></tr><tr><td><code>energy</code></td><td><code>value.energy</code></td><td><code>Wh</code>, <code>kWh</code></td></tr><tr><td><code>energy_storage</code></td><td><code>value.energy</code></td><td><code>Wh</code>, <code>kWh</code></td></tr><tr><td><code>reactive_power</code></td><td><code>value.power.reactive</code></td><td><code>var</code>, <code>kvar</code>, <code>kVar</code></td></tr><tr><td><code>reactive_energy</code></td><td><code>value.energy.reactive</code></td><td><code>varh</code>, <code>kvarh</code>, <code>kVarh</code></td></tr><tr><td><code>frequency</code></td><td><code>value.frequency</code></td><td><code>Hz</code></td></tr><tr><td><code>pressure</code></td><td><code>value.pressure</code></td><td><code>hPa</code>, <code>mbar</code></td></tr><tr><td><code>atmospheric_pressure</code></td><td><code>value.pressure</code></td><td><code>hPa</code>, <code>mbar</code></td></tr><tr><td><code>illuminance</code></td><td><code>value.brightness</code></td><td><code>lx</code>, <code>lux</code></td></tr><tr><td><code>distance</code></td><td><code>value.distance</code></td><td><code>m</code>, <code>km</code>, <code>cm</code>, <code>mm</code>, <code>mi</code>, <code>nmi</code>, <code>yd</code>, <code>ft</code>, <code>in</code></td></tr><tr><td><code>duration</code></td><td><code>value.interval</code></td><td><code>s</code>, <code>ms</code>, <code>h</code>, <code>d</code></td></tr><tr><td><code>wind_speed</code></td><td><code>value.speed</code></td><td><code>m/s</code>, <code>km/h</code>, <code>mph</code>, <code>kn</code></td></tr><tr><td><code>volume_flow_rate</code></td><td><code>value.flow</code></td><td><code>m³/h</code></td></tr><tr><td><code>signal_strength</code></td><td><code>value.rssi</code></td><td><code>dBm</code></td></tr><tr><td><code>aqi</code></td><td><code>value.airquality</code></td><td>—</td></tr><tr><td><code>carbon_dioxide</code></td><td><code>value.co2</code></td><td><code>ppm</code></td></tr><tr><td><code>carbon_monoxide</code></td><td><code>value.co</code></td><td><code>ppm</code></td></tr><tr><td><code>nitrogen_monoxide</code></td><td><code>value.no</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>nitrogen_dioxide</code></td><td><code>value.no2</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>ozone</code></td><td><code>value.o3</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>sulphur_dioxide</code></td><td><code>value.so2</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>pm1</code></td><td><code>value.pm1</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>pm25</code></td><td><code>value.pm25</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>pm10</code></td><td><code>value.pm10</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>radon</code></td><td><code>value.rn</code></td><td><code>Bq/m³</code></td></tr><tr><td><code>volatile_organic_compounds</code></td><td><code>value.tvoc</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>volatile_organic_compounds_parts</code></td><td><code>value.tvoc</code></td><td><code>ppb</code></td></tr></tbody></table><h2 id="binary" tabindex="-1">Binärsensoren <a class="header-anchor" href="#binary" aria-label="Permalink to &quot;Binärsensoren {#binary}&quot;">​</a></h2><p>Nur bei echten booleschen Werten und passendem Objekttyp. Die üblichen HA-Texte <code>on</code> und <code>off</code> bleiben unverändert und bekommen durch dieses Skript keine boolesche Rolle. Bei <code>battery</code> bedeutet wahr Batterie schwach; bei <code>lock</code> bedeutet wahr entriegelt.</p><table tabindex="0"><thead><tr><th>HA-Geräteklasse</th><th>ioBroker-Rolle</th></tr></thead><tbody><tr><td><code>battery</code></td><td><code>indicator.lowbat</code></td></tr><tr><td><code>connectivity</code></td><td><code>indicator.reachable</code></td></tr><tr><td><code>door</code></td><td><code>sensor.door</code></td></tr><tr><td><code>garage_door</code></td><td><code>sensor.door</code></td></tr><tr><td><code>window</code></td><td><code>sensor.window</code></td></tr><tr><td><code>opening</code></td><td><code>sensor.contact</code></td></tr><tr><td><code>lock</code></td><td><code>sensor.lock</code></td></tr><tr><td><code>motion</code></td><td><code>sensor.motion</code></td></tr><tr><td><code>moisture</code></td><td><code>sensor.alarm.flood</code></td></tr><tr><td><code>smoke</code></td><td><code>sensor.alarm.fire</code></td></tr><tr><td><code>carbon_monoxide</code></td><td><code>sensor.alarm.co</code></td></tr><tr><td><code>light</code></td><td><code>sensor.light</code></td></tr><tr><td><code>sound</code></td><td><code>sensor.noise</code></td></tr><tr><td><code>problem</code></td><td><code>indicator.error</code></td></tr><tr><td><code>running</code></td><td><code>indicator.working</code></td></tr></tbody></table><h2 id="conditional" tabindex="-1">Weitere Zuordnungen aus dem Vergleich <a class="header-anchor" href="#conditional" aria-label="Permalink to &quot;Weitere Zuordnungen aus dem Vergleich {#conditional}&quot;">​</a></h2><p>Im reinen Rollenmodus werden diese Fälle nicht automatisch umgesetzt. Der virtuelle Modus übernimmt die unten genannten Light- und Schaltfunktionen mit den beschriebenen Prüfungen; Füllstand, Verbrauch/Einspeisung und mehrdeutige Messklassen werden weiterhin nicht geraten.</p><table tabindex="0"><thead><tr><th>HA-Klasse/Funktion</th><th>Mögliche Rolle</th><th>Noch erforderlich</th></tr></thead><tbody><tr><td><code>volume_storage</code></td><td><code>value.fill</code></td><td>Tatsächlichen Behälterfüllstand bestätigen</td></tr><tr><td><code>water</code>, <code>gas</code></td><td>Allgemeiner Messwert</td><td>Verbrauch ist kein Füllstand</td></tr><tr><td><code>energy</code></td><td><code>value.energy.consumed</code> / <code>value.energy.produced</code></td><td>Verbrauch/Einspeisung ausdrücklich feststellen</td></tr><tr><td><code>speed</code></td><td><code>value.speed</code></td><td>Nicht pauschal als Windgeschwindigkeit behandeln</td></tr><tr><td><code>moisture</code> als Zahl</td><td>Allgemeiner Messwert</td><td>Nicht mit binärem Wasseralarm verwechseln</td></tr><tr><td>Helligkeitsrückmeldung</td><td><code>value.dimmer</code></td><td>Prozentwert und Light-Funktion bestätigen</td></tr><tr><td>Helligkeitsvorgabe</td><td><code>level.dimmer</code></td><td>Separaten Rückkanal korrekt anbinden</td></tr><tr><td>Schaltzustand</td><td><code>sensor.switch</code></td><td>Booleschen Wert normalisieren</td></tr><tr><td>Schaltbefehl</td><td><code>switch</code> / <code>switch.light</code></td><td><code>/set</code> anbinden; keinen Befehl zur Einrichtung senden</td></tr><tr><td>Farbtemperaturvorgabe</td><td><code>level.color.temperature</code></td><td>Kelvin, Grenzen und Rückkanal</td></tr><tr><td>Effektauswahl</td><td><code>level.effect</code></td><td>Effektliste und Rückkanal</td></tr><tr><td>RGB-Steuerung</td><td><code>level.color.rgb</code></td><td>JSON-Array in Hexfarbe umwandeln</td></tr></tbody></table><p>Für <code>occupancy</code>, <code>presence</code>, <code>moving</code>, <code>plug</code>, binäres <code>power</code>, <code>battery_charging</code>, <code>cold</code>, <code>heat</code>, binäres <code>gas</code>, <code>glass_break</code>, <code>safety</code>, <code>tamper</code>, <code>update</code> und <code>vibration</code> wird keine Spezialrolle geraten. Allgemeine <code>sensor</code>-/<code>indicator</code>-Rollen oder eigene Regeln sind möglich, gehören aber nicht zur sicheren Automatik. Auch alle weiteren nicht aufgeführten Klassen bleiben unverändert.</p><h2 id="restore" tabindex="-1">Wiederherstellung <a class="header-anchor" href="#restore" aria-label="Permalink to &quot;Wiederherstellung {#restore}&quot;">​</a></h2><p>Skript stoppen, <code>mode: &#39;restore&#39;</code> einstellen und erneut starten. Das Skript stellt nur eigene Rollenänderungen wieder her, wenn die aktuelle Rolle und der Datentyp noch zu seinem Sicherungseintrag passen. Nachträgliche manuelle Rollenänderungen bleiben bestehen. Eigene unveränderte Aliase werden entfernt; bearbeitete oder fremde Aliase bleiben erhalten. MQTT-Originalwerte werden nicht gelöscht.</p><p>Danach das Skript stoppen. Sicherung und Ausnahmeliste aufbewahren. Bereits protokollierte Datenpunkte werden im selben Journal nicht erneut übernommen; ein neuer Durchgang benötigt bewusst einen neuen <code>backupId</code> und bei Aliasen einen freien <code>aliasRoot</code>.</p><p>Lokal mit simulierten ioBroker-APIs auf Vorschau, Sicherungsfehler, Typen, Einheiten, manuelle Änderungen, Aliase und Wiederherstellung geprüft. Noch kein Installationstest auf einem realen ioBroker-System.</p><p><a href="https://www.home-assistant.io/integrations/sensor/#device-class" target="_blank" rel="noreferrer">Home Assistant: Sensor</a> · <a href="https://www.home-assistant.io/integrations/binary_sensor/#device-class" target="_blank" rel="noreferrer">Home Assistant: Binary sensor</a> · <a href="https://www.iobroker.com/docs/dev/stateroles.md" target="_blank" rel="noreferrer">ioBroker: State roles</a> · <a href="https://github.com/ioBroker/ioBroker.javascript/blob/v10.4.10/docs/en/javascript.md" target="_blank" rel="noreferrer">ioBroker: JavaScript API</a></p>`,41)])])}const p=t(o,[["render",i]]);export{g as __pageData,p as default};
